package com.inventoryhover;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * Floating chart of recent clicks: a clean click rate at the top, stacked bars
 * over the chosen time window (good, missed, refused, double), and a legend
 * with the counts for the window. Size, window and parts are configurable, and
 * text shortens to fit narrow charts. Movable like any RuneLite overlay box.
 */
class ClickChartOverlay extends Overlay
{
	private static final int PAD = 6;
	private static final int BAR_GAP = 1;
	// Space kept between the title and the clean click rate
	private static final int TITLE_GAP = 8;

	private static final Color GOOD = new Color(80, 200, 120);
	private static final Color MISSED = new Color(230, 70, 70);
	private static final Color REFUSED = new Color(240, 200, 40);
	private static final Color DOUBLE = new Color(240, 130, 40);
	private static final Color AXIS = new Color(255, 255, 255, 60);
	private static final Color LABEL = new Color(200, 200, 200);
	private static final Color AVERAGE = new Color(255, 255, 255, 200);

	// Draw order from the baseline up; misses sit on top so they stand out
	private static final Color[] STACK = {GOOD, DOUBLE, REFUSED, MISSED};
	private static final String[] NAMES = {"Good", "Double", "Refused", "Missed"};

	private final InventoryHoverHighlightPlugin plugin;
	private final InventoryHoverHighlightConfig config;

	@Inject
	ClickChartOverlay(InventoryHoverHighlightPlugin plugin, InventoryHoverHighlightConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.clickChart())
		{
			return null;
		}

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		boolean ticks = config.clickChartUnit() == InventoryHoverHighlightConfig.ChartUnit.TICKS;
		int interval = config.clickChartInterval();
		int barCount = config.clickChartBars();
		int[][] history = ticks
			? plugin.stats.tickHistory(interval, barCount)
			: plugin.stats.secondHistory(interval, barCount);

		// Per bar: good, double, refused, missed. Good excludes the clicks that went wrong.
		int[][] bars = new int[history.length][4];
		int[] totals = new int[4];
		for (int i = 0; i < history.length; i++)
		{
			int[] h = history[i];
			int useful = h[ClickStats.Kind.USEFUL.ordinal()];
			int doubles = h[ClickStats.Kind.DOUBLE.ordinal()];
			int refused = h[ClickStats.Kind.REJECTED.ordinal()];
			int missed = h[ClickStats.Kind.MISSED.ordinal()];
			bars[i][0] = Math.max(0, useful - doubles - refused);
			bars[i][1] = doubles;
			bars[i][2] = refused;
			bars[i][3] = missed;
			for (int k = 0; k < 4; k++)
			{
				totals[k] += bars[i][k];
			}
		}

		Font small = FontManager.getRunescapeSmallFont();
		Font bold = FontManager.getRunescapeBoldFont();
		FontMetrics smallMetrics = graphics.getFontMetrics(small);
		FontMetrics boldMetrics = graphics.getFontMetrics(bold);
		int lineHeight = smallMetrics.getHeight();
		int width = config.clickChartWidth();
		int inner = width - PAD * 2;
		int chartHeight = config.clickChartHeight();

		int all = totals[0] + totals[1] + totals[2] + totals[3];
		String rate = all == 0 ? "-" : (totals[0] * 100 / all) + "%" + (inner >= 140 ? " clean" : "");
		String window = ticks ? interval * barCount + "t" : formatWindow(interval * barCount);
		// Shorten the title until it fits beside the rate, or drop it
		String title = null;
		for (String option : new String[]{"Clicks, last " + window, "Clicks " + window, window})
		{
			if (boldMetrics.stringWidth(option) + TITLE_GAP + boldMetrics.stringWidth(rate) <= inner)
			{
				title = option;
				break;
			}
		}

		boolean legend = config.clickChartLegend();
		boolean axis = config.clickChartTimeAxis();
		// Two legend columns when they fit, else one
		int legendColumns = 2;
		for (int k = 0; k < 4; k++)
		{
			if (11 + smallMetrics.stringWidth(NAMES[k] + " " + totals[k]) > inner / 2)
			{
				legendColumns = 1;
			}
		}
		int legendRows = 4 / legendColumns;

		int titleHeight = boldMetrics.getHeight();
		int height = PAD + titleHeight + 4 + chartHeight
			+ (axis ? lineHeight + 2 : 2)
			+ (legend ? lineHeight * legendRows + 2 : 0) + PAD;

		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fill(new RoundRectangle2D.Float(0, 0, width, height, 8, 8));

		// Title and clean click rate
		int y = PAD + boldMetrics.getAscent();
		graphics.setFont(bold);
		if (title != null)
		{
			graphics.setColor(Color.WHITE);
			graphics.drawString(title, PAD, y);
		}
		graphics.setColor(all == 0 ? LABEL : rateColor(totals[0] * 100 / all));
		graphics.drawString(rate, width - PAD - boldMetrics.stringWidth(rate), y);

		// Bars
		int chartTop = PAD + titleHeight + 4;
		int chartBottom = chartTop + chartHeight;
		int max = 1;
		for (int[] bar : bars)
		{
			max = Math.max(max, bar[0] + bar[1] + bar[2] + bar[3]);
		}

		float slot = (float) inner / bars.length;
		for (int i = 0; i < bars.length; i++)
		{
			int x = PAD + Math.round(i * slot);
			int w = Math.max(1, Math.round((i + 1) * slot) - Math.round(i * slot) - BAR_GAP);
			int top = chartBottom;
			for (int k = 0; k < 4; k++)
			{
				int h = Math.round((float) bars[i][k] / max * chartHeight);
				if (h <= 0)
				{
					continue;
				}
				top -= h;
				graphics.setColor(STACK[k]);
				graphics.fillRect(x, top, w, h);
			}
		}

		if (config.clickChartAverage())
		{
			drawAverage(graphics, bars, max, slot, chartBottom, chartHeight, config.clickChartAverageBars());
		}

		graphics.setColor(AXIS);
		graphics.drawLine(PAD, chartBottom, width - PAD, chartBottom);

		graphics.setFont(small);
		if (all == 0)
		{
			String empty = "No clicks yet";
			graphics.setColor(LABEL);
			graphics.drawString(empty, Math.max(PAD, (width - smallMetrics.stringWidth(empty)) / 2),
				chartTop + chartHeight / 2 + smallMetrics.getAscent() / 2);
		}

		int below = chartBottom + 2;
		if (axis)
		{
			y = chartBottom + smallMetrics.getAscent() + 1;
			graphics.setColor(LABEL);
			graphics.drawString(window + " ago", PAD, y);
			String now = "now";
			graphics.drawString(now, width - PAD - smallMetrics.stringWidth(now), y);
			below = chartBottom + lineHeight + 2;
		}

		if (legend)
		{
			int column = inner / legendColumns;
			for (int k = 0; k < 4; k++)
			{
				int x = PAD + (k % legendColumns) * column;
				int rowY = below + (k / legendColumns) * lineHeight;
				graphics.setColor(STACK[k]);
				graphics.fillRect(x, rowY + 2, 7, 7);
				graphics.setColor(Color.WHITE);
				graphics.drawString(NAMES[k] + " " + totals[k], x + 11, rowY + smallMetrics.getAscent());
			}
		}

		return new Dimension(width, height);
	}

	/** Line through the average of the last {@code span} bar totals, at each bar's center. */
	private static void drawAverage(Graphics2D graphics, int[][] bars, int max, float slot, int chartBottom,
		int chartHeight, int span)
	{
		Path2D line = new Path2D.Float();
		double sum = 0;
		for (int i = 0; i < bars.length; i++)
		{
			sum += bars[i][0] + bars[i][1] + bars[i][2] + bars[i][3];
			if (i >= span)
			{
				int[] old = bars[i - span];
				sum -= old[0] + old[1] + old[2] + old[3];
			}
			double average = sum / Math.min(i + 1, span);
			float x = PAD + (i + 0.5f) * slot;
			float y = (float) (chartBottom - average / max * chartHeight);
			if (i == 0)
			{
				line.moveTo(x, y);
			}
			else
			{
				line.lineTo(x, y);
			}
		}
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.setColor(AVERAGE);
		graphics.draw(line);
	}

	/** A window length like 45s, 2m or 2m30s. */
	private static String formatWindow(int seconds)
	{
		if (seconds < 120)
		{
			return seconds + "s";
		}
		return (seconds / 60) + "m" + (seconds % 60 == 0 ? "" : (seconds % 60) + "s");
	}

	private static Color rateColor(int percent)
	{
		return percent >= 90 ? GOOD : percent >= 75 ? REFUSED : MISSED;
	}
}

package com.inventoryhover;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTabbedPane;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

/**
 * Side panel with the settings Export and Import buttons, the switch practice
 * start button and a chart of practice progress across sessions.
 */
class ClickHelpersPanel extends PluginPanel
{
	private static final Color SWITCH_LINE = new Color(90, 170, 255);
	private static final Color ACCURACY_LINE = new Color(80, 200, 120);

	private final InventoryHoverHighlightPlugin plugin;
	private final ConfigManager configManager;
	private final ColorPickerManager colorPickerManager;

	private final JLabel shareStatus = new JLabel(" ");
	private final JComboBox<String> loadoutBox = new JComboBox<>();
	private final JLabel loadoutStatus = new JLabel(" ");
	private final JButton practiceButton = new JButton();
	private final JLabel sessionLabel = new JLabel();
	private final ProgressChart chart = new ProgressChart();
	private final JPanel historyList = new JPanel();

	ClickHelpersPanel(InventoryHoverHighlightPlugin plugin, InventoryHoverHighlightConfig config,
		ConfigManager configManager, ColorPickerManager colorPickerManager)
	{
		this.plugin = plugin;
		this.configManager = configManager;
		this.colorPickerManager = colorPickerManager;
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel settingsTab = tabPage();
		JPanel practiceTab = tabPage();

		settingsTab.add(heading("Export / import"));
		JPanel shareButtons = new JPanel(new GridLayout(1, 2, 6, 0));
		JButton export = new JButton("Export");
		export.setToolTipText("Copy all Click Helpers settings to the clipboard as JSON");
		export.addActionListener(e -> shareStatus.setText(wrap(plugin.exportSettings())));
		JButton importButton = new JButton("Import");
		importButton.setToolTipText("Apply Click Helpers settings JSON from the clipboard");
		importButton.addActionListener(e -> shareStatus.setText(wrap(plugin.importSettings())));
		shareButtons.add(export);
		shareButtons.add(importButton);
		settingsTab.add(left(shareButtons));
		shareStatus.setFont(FontManager.getRunescapeSmallFont());
		settingsTab.add(left(shareStatus));

		settingsTab.add(heading("Loadouts"));
		JTextField loadoutName = new JTextField();
		loadoutName.setToolTipText("Name to save the current settings under");
		settingsTab.add(left(loadoutName));
		JButton saveLoadout = new JButton("Save current settings");
		saveLoadout.addActionListener(e ->
		{
			loadoutStatus.setText(wrap(plugin.loadouts().saveLoadout(loadoutName.getText())));
			refreshLoadouts(loadoutName.getText().trim());
		});
		settingsTab.add(left(saveLoadout));
		settingsTab.add(left(loadoutBox));
		JPanel loadoutButtons = new JPanel(new GridLayout(1, 2, 6, 0));
		JButton load = new JButton("Load");
		load.addActionListener(e ->
			loadoutStatus.setText(wrap(plugin.loadouts().loadLoadout((String) loadoutBox.getSelectedItem()))));
		JButton delete = new JButton("Delete");
		delete.addActionListener(e ->
		{
			loadoutStatus.setText(wrap(plugin.loadouts().deleteLoadout((String) loadoutBox.getSelectedItem())));
			refreshLoadouts(null);
		});
		loadoutButtons.add(load);
		loadoutButtons.add(delete);
		settingsTab.add(left(loadoutButtons));
		loadoutStatus.setFont(FontManager.getRunescapeSmallFont());
		settingsTab.add(left(loadoutStatus));
		refreshLoadouts(null);

		settingsTab.add(heading("Feeling lucky"));
		JButton randomize = new JButton("Randomize all settings");
		randomize.setToolTipText("Random values for every setting except the click chart, hotkeys and text lists; turns off tab sync");
		randomize.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this,
				"Randomize all Click Helpers settings?\nSave a loadout first to keep your current ones.",
				"Randomize settings", JOptionPane.OK_CANCEL_OPTION);
			if (answer == JOptionPane.OK_OPTION)
			{
				loadoutStatus.setText(wrap(plugin.loadouts().randomizeAll()));
			}
		});
		settingsTab.add(left(randomize));

		practiceTab.add(heading("Switch practice"));
		practiceButton.addActionListener(e -> plugin.togglePractice());
		practiceTab.add(left(practiceButton));
		sessionLabel.setFont(FontManager.getRunescapeSmallFont());
		practiceTab.add(left(sessionLabel));
		practiceTab.add(left(chart));

		JPanel legend = new JPanel(new GridLayout(1, 2));
		legend.add(legendLabel("Switch time", SWITCH_LINE));
		legend.add(legendLabel("Accuracy", ACCURACY_LINE));
		practiceTab.add(left(legend));

		historyList.setLayout(new BoxLayout(historyList, BoxLayout.Y_AXIS));
		practiceTab.add(left(historyList));

		JButton clear = new JButton("Clear history");
		clear.addActionListener(e -> plugin.clearPracticeHistory());
		practiceTab.add(left(clear));

		practiceTab.add(heading("Practice settings"));
		JPanel settings = new JPanel(new GridLayout(0, 2, 4, 4));
		spinner(settings, "Slots per switch", "practiceTargets", config.practiceTargets(), 1, 28, 1);
		spinner(settings, "Pause (ms)", "practiceRoundDelay", config.practiceRoundDelay(), 0, 5000, 100);
		check(settings, "Random extra pause", "practiceRandomDelay", config.practiceRandomDelay());
		label(settings, "Time limit (s, 0 off)");
		JSpinner timeLimit = new JSpinner(new SpinnerNumberModel(config.practiceTimeLimitSeconds(), 0.0, 30.0, 0.1));
		timeLimit.addChangeListener(e -> set("practiceTimeLimitSeconds", timeLimit.getValue()));
		settings.add(timeLimit);
		check(settings, "Timer bar", "practiceTimerBar", config.practiceTimerBar());
		spinner(settings, "Rounds (0 endless)", "practiceRounds", config.practiceRounds(), 0, 500, 5);
		check(settings, "Click in order", "practiceOrdered", config.practiceOrdered());
		check(settings, "Number targets", "practiceNumbers", config.practiceNumbers());
		combo(settings, "Stats", "practiceStatsMode", config.practiceStatsMode());
		color(settings, "Target color", "practiceTargetColor", config.practiceTargetColor());
		color(settings, "Hit color", "practiceHitColor", config.practiceHitColor());
		practiceTab.add(left(settings));

		// Settings tools and practice live on separate tabs so they never mix
		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Loadouts", top(settingsTab));
		tabs.addTab("Practice", top(practiceTab));
		add(tabs, BorderLayout.NORTH);
		update(false, null, new ArrayList<>());
	}

	/** Shows the practice state; call on the Swing thread. */
	void update(boolean practicing, SwitchPractice.Summary current, List<SwitchPractice.Summary> history)
	{
		practiceButton.setText(practicing ? "Stop practice" : "Start practice");
		if (current == null)
		{
			sessionLabel.setText(practicing ? "Click the lit slots in your inventory" : "Not practicing");
		}
		else
		{
			sessionLabel.setText(wrap(String.format("%d rounds: %.0f ms average, best %d ms, %.1f ticks,"
					+ " %.0f%% in 1 tick, %.0f%% accuracy, %d timeouts",
				current.rounds, current.switchMillis, current.bestSwitchMillis, current.ticks, current.oneTickRate,
				current.accuracy, current.timeouts)));
		}

		List<SwitchPractice.Summary> points = new ArrayList<>(history);
		if (current != null)
		{
			points.add(current);
		}
		chart.setPoints(points);

		historyList.removeAll();
		SimpleDateFormat format = new SimpleDateFormat("MMM d HH:mm");
		for (int i = history.size() - 1; i >= Math.max(0, history.size() - 8); i--)
		{
			SwitchPractice.Summary s = history.get(i);
			JLabel row = new JLabel(String.format("%s  %d rnd  %.0f ms  %.0f%% 1t  %.0f%%",
				format.format(new Date(s.time)), s.rounds, s.switchMillis, s.oneTickRate, s.accuracy));
			row.setFont(FontManager.getRunescapeSmallFont());
			row.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			historyList.add(row);
		}
		revalidate();
		repaint();
	}

	/** Refills the loadout dropdown, selecting {@code select} when given. */
	private void refreshLoadouts(String select)
	{
		loadoutBox.removeAllItems();
		for (String name : plugin.loadouts().loadoutNames())
		{
			loadoutBox.addItem(name);
		}
		if (select != null && !select.isEmpty())
		{
			loadoutBox.setSelectedItem(select);
		}
	}

	private void set(String key, Object value)
	{
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, key, value);
	}

	private static JLabel label(JPanel settings, String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		settings.add(label);
		return label;
	}

	private void spinner(JPanel settings, String text, String key, int value, int min, int max, int step)
	{
		label(settings, text);
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, min, max, step));
		spinner.addChangeListener(e -> set(key, spinner.getValue()));
		settings.add(spinner);
	}

	private void check(JPanel settings, String text, String key, boolean value)
	{
		label(settings, text);
		JCheckBox box = new JCheckBox();
		box.setSelected(value);
		box.addActionListener(e -> set(key, box.isSelected()));
		settings.add(box);
	}

	private <E extends Enum<E>> void combo(JPanel settings, String text, String key, E value)
	{
		label(settings, text);
		JComboBox<E> box = new JComboBox<>(value.getDeclaringClass().getEnumConstants());
		box.setSelectedItem(value);
		box.addActionListener(e -> set(key, box.getSelectedItem()));
		settings.add(box);
	}

	private void color(JPanel settings, String text, String key, Color value)
	{
		label(settings, text);
		JButton swatch = new JButton();
		swatch.setBackground(value);
		swatch.setToolTipText("Click to pick a color");
		swatch.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				RuneliteColorPicker picker = colorPickerManager.create(swatch, swatch.getBackground(), text, false);
				picker.setOnColorChange(c ->
				{
					swatch.setBackground(c);
					set(key, c);
				});
				picker.setVisible(true);
			}
		});
		settings.add(swatch);
	}

	private static JPanel tabPage()
	{
		JPanel page = new JPanel();
		page.setLayout(new BoxLayout(page, BoxLayout.Y_AXIS));
		page.setBorder(new EmptyBorder(4, 0, 0, 0));
		return page;
	}

	/** Keeps a tab page's rows at the top instead of stretching them over the tab. */
	private static JPanel top(JPanel page)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.add(page, BorderLayout.NORTH);
		return holder;
	}

	private static String wrap(String text)
	{
		return "<html><body style='width: 170px'>" + text + "</body></html>";
	}

	private static JComponent heading(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(new EmptyBorder(8, 0, 4, 0));
		return left(label);
	}

	private static JLabel legendLabel(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	private static JComponent left(JComponent component)
	{
		component.setAlignmentX(LEFT_ALIGNMENT);
		return component;
	}

	/** Line chart of switch time and accuracy per practice session, oldest on the left. */
	private static class ProgressChart extends JComponent
	{
		private static final int HEIGHT = 120;
		private List<SwitchPractice.Summary> points = new ArrayList<>();

		ProgressChart()
		{
			setPreferredSize(new Dimension(PANEL_WIDTH - 16, HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
			setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
		}

		void setPoints(List<SwitchPractice.Summary> points)
		{
			this.points = points;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D graphics = (Graphics2D) g.create();
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			graphics.setColor(ColorScheme.DARKER_GRAY_COLOR);
			graphics.fillRect(0, 0, w, h);

			graphics.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics metrics = graphics.getFontMetrics();
			if (points.isEmpty())
			{
				String empty = "Finish a practice round to see progress";
				graphics.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				graphics.drawString(empty, Math.max(2, (w - metrics.stringWidth(empty)) / 2), h / 2);
				graphics.dispose();
				return;
			}

			int pad = 6;
			int top = pad + metrics.getHeight();
			int bottom = h - pad;
			double maxMillis = 1;
			for (SwitchPractice.Summary s : points)
			{
				maxMillis = Math.max(maxMillis, s.switchMillis);
			}

			graphics.setColor(SWITCH_LINE);
			graphics.drawString(String.format("%.0f ms", maxMillis), pad, pad + metrics.getAscent());
			graphics.setColor(ACCURACY_LINE);
			String full = "100%";
			graphics.drawString(full, w - pad - metrics.stringWidth(full), pad + metrics.getAscent());

			graphics.setColor(new Color(255, 255, 255, 40));
			graphics.drawLine(pad, bottom, w - pad, bottom);

			drawLine(graphics, w, top, bottom, pad, SWITCH_LINE, maxMillis, true);
			drawLine(graphics, w, top, bottom, pad, ACCURACY_LINE, 100, false);
			graphics.dispose();
		}

		private void drawLine(Graphics2D graphics, int w, int top, int bottom, int pad, Color color, double max,
			boolean switchTime)
		{
			Path2D path = new Path2D.Double();
			int n = points.size();
			for (int i = 0; i < n; i++)
			{
				SwitchPractice.Summary s = points.get(i);
				double value = switchTime ? s.switchMillis : s.accuracy;
				double x = n == 1 ? w / 2.0 : pad + (w - pad * 2) * (double) i / (n - 1);
				double y = bottom - (bottom - top) * Math.min(1, value / max);
				if (i == 0)
				{
					path.moveTo(x, y);
				}
				else
				{
					path.lineTo(x, y);
				}
				graphics.setColor(color);
				graphics.fillOval((int) x - 2, (int) y - 2, 4, 4);
			}
			graphics.setColor(color);
			graphics.setStroke(new BasicStroke(1.5f));
			graphics.draw(path);
		}
	}
}

package com.inventoryhover;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Recent click counts for the click chart, kept both per second and per game
 * tick, long enough for the longest chart window. Written on the client thread
 * and read on the Swing thread, so every access is synchronized.
 */
class ClickStats
{
	enum Kind
	{
		/** A click the game accepted on a slot, prayer or spell. */
		USEFUL,
		/** A click on an empty slot or a gap. */
		MISSED,
		/** A click the game refused with a message. */
		REJECTED,
		/** A second click on the same slot in one tick. */
		DOUBLE
	}

	private static final long SECOND_MILLIS = 1_000;

	/** Longest history kept, in seconds and in ticks (the same two hours). */
	private static final int KEEP_SECONDS = 7200;
	private static final int KEEP_TICKS = 12000;

	/** Counts for one second or one tick. */
	static class Bucket
	{
		final long start;
		final int[] counts = new int[Kind.values().length];

		Bucket(long start)
		{
			this.start = start;
		}
	}

	private final Deque<Bucket> seconds = new ArrayDeque<>();
	private final Deque<Bucket> ticks = new ArrayDeque<>();

	/** Latest game tick count, set by the plugin every tick. */
	private int tick;

	synchronized void setTick(int tick)
	{
		this.tick = tick;
	}

	synchronized void add(Kind kind)
	{
		count(seconds, System.currentTimeMillis() / SECOND_MILLIS, kind);
		count(ticks, tick, kind);
		trim();
	}

	private static void count(Deque<Bucket> buckets, long start, Kind kind)
	{
		Bucket last = buckets.peekLast();
		if (last == null || last.start != start)
		{
			last = new Bucket(start);
			buckets.addLast(last);
		}
		last.counts[kind.ordinal()]++;
	}

	/** Counts per bar of {@code interval} seconds for the last {@code bars} bars, oldest first. */
	synchronized int[][] secondHistory(int interval, int bars)
	{
		trim();
		return history(seconds, System.currentTimeMillis() / SECOND_MILLIS, interval, bars);
	}

	/** Counts per bar of {@code interval} game ticks for the last {@code bars} bars, oldest first. */
	synchronized int[][] tickHistory(int interval, int bars)
	{
		trim();
		return history(ticks, tick, interval, bars);
	}

	/**
	 * Bars cover fixed slices of time, so a finished bar never changes; slicing
	 * by age instead would shift clicks between bars every frame.
	 */
	private static int[][] history(Deque<Bucket> buckets, long now, int interval, int bars)
	{
		long newest = now / interval;
		int[][] history = new int[bars][Kind.values().length];
		for (Bucket bucket : buckets)
		{
			long back = newest - bucket.start / interval;
			if (back < 0 || back >= bars)
			{
				continue;
			}
			int index = bars - 1 - (int) back;
			for (int k = 0; k < bucket.counts.length; k++)
			{
				history[index][k] += bucket.counts[k];
			}
		}
		return history;
	}

	synchronized void reset()
	{
		seconds.clear();
		ticks.clear();
	}

	private void trim()
	{
		long oldestSecond = System.currentTimeMillis() / SECOND_MILLIS - KEEP_SECONDS;
		while (!seconds.isEmpty() && seconds.peekFirst().start < oldestSecond)
		{
			seconds.removeFirst();
		}
		// Tick counts restart on login, so also drop anything from a later count
		while (!ticks.isEmpty() && (ticks.peekFirst().start < tick - KEEP_TICKS || ticks.peekFirst().start > tick))
		{
			ticks.removeFirst();
		}
	}
}

