		g.dispose();
		return image;
	}

	// Eat and drink delays

	/** Starts the eat or drink delay; returns true when the click falls in a running delay. */
	private boolean startConsumeDelay(String option, int itemId)
	{
		Consumable kind = null;
		if ("Eat".equalsIgnoreCase(option))
		{
			kind = isComboFood(itemId) ? Consumable.COMBO_FOOD : Consumable.FOOD;
		}
		else if ("Drink".equalsIgnoreCase(option))
		{
			kind = Consumable.POTION;
		}

		if (kind == null)
		{
			return false;
		}
		// A click during the delay is ignored by the game, so it does not restart the delay
		if (consumeRemaining(kind) > 0)
		{
			return true;
		}

		// Food, then a potion, then a karambwan can all go in one tick, but not in
		// another order: a potion blocks food for the rest of its tick, and a
		// karambwan blocks food for its whole delay and potions for its tick
		int tick = client.getTickCount();
		switch (kind)
		{
			case FOOD:
				extendDelay(Consumable.FOOD, tick, foodDelayTicks(client.getItemDefinition(itemId).getName()));
				break;
			case POTION:
				extendDelay(Consumable.POTION, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.FOOD, tick, 1);
				break;
			case COMBO_FOOD:
				extendDelay(Consumable.COMBO_FOOD, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.FOOD, tick, CONSUME_DELAY_TICKS);
				extendDelay(Consumable.POTION, tick, 1);
				break;
		}
		return false;
	}

	/** Makes a delay last at least {@code ticks} from {@code tick}. */
	private void extendDelay(Consumable kind, int tick, int ticks)
	{
		int[] delay = consumeDelays.get(kind);
		if (delay == null || delay[1] < tick + ticks)
		{
			consumeDelays.put(kind, new int[]{tick, tick + ticks});
		}
	}

	/**
	 * Eat delay of a food by name. Most food is 3 ticks; pies, pizzas, cakes and
	 * giant crab meat are faster.
	 */
	static int foodDelayTicks(String name)
	{
		String n = name.toLowerCase();
		boolean half = n.startsWith("half ") || n.startsWith("1/2 ");
		if (n.contains("giant crab meat"))
		{
			return 2;
		}
		if (n.endsWith(" pizza"))
		{
			return half ? 2 : 1;
		}
		if (n.endsWith(" pie"))
		{
			// Apple, meat and redberry pies take 2 ticks for the second half; members' pies 1
			boolean slowHalf = n.endsWith("apple pie") || n.endsWith("meat pie") || n.endsWith("redberry pie");
			return half && slowHalf ? 2 : 1;
		}
		if (n.equals("cake") || n.equals("2/3 cake") || n.equals("chocolate cake") || n.equals("2/3 chocolate cake"))
		{
			return 2;
		}
		return CONSUME_DELAY_TICKS;
	}

	/** Ticks left on a delay, counting the current tick as a whole one, or 0. */
	int consumeRemaining(Consumable kind)
	{
		int[] delay = consumeDelays.get(kind);
		return delay == null ? 0 : Math.max(0, delay[1] - client.getTickCount());
	}

	/** Full length in ticks of the running delay, for drawing how much is left. */
	int consumeLength(Consumable kind)
	{
		int[] delay = consumeDelays.get(kind);
		return delay == null ? CONSUME_DELAY_TICKS : Math.max(1, delay[1] - delay[0]);
	}

	/** The delay an item shares, from its inventory actions, or null. */
	Consumable consumableFor(int itemId)
	{
		return consumableCache.computeIfAbsent(itemId, id ->
		{
			ItemComposition item = client.getItemDefinition(id);
			for (String action : item.getInventoryActions())
			{
				if ("Eat".equalsIgnoreCase(action))
				{
					return isComboFood(id) ? Consumable.COMBO_FOOD : Consumable.FOOD;
				}
				if ("Drink".equalsIgnoreCase(action))
				{
					return Consumable.POTION;
				}
			}
			return null;
		});
	}

	private boolean isComboFood(int itemId)
	{
		return client.getItemDefinition(itemId).getName().toLowerCase().contains("karambwan");
	}

	// Item hiding

	private void parseItemLists()
	{
		fightActions = Text.fromCSV(config.fightActions()).stream()
			.map(String::toLowerCase)
			.collect(Collectors.toSet());
		alwaysShow = Text.fromCSV(config.alwaysShowItems());
		cuePrayers = Text.fromCSV(config.cuePrayers());
	}

	private boolean hidingActive()
	{
		return config.hideItems() && (Keybind.NOT_SET.equals(config.hideItemsHotkey()) || itemsHidden);
	}

	/** Whether an item has no fight action, so it can be hidden. */
	private boolean isNonFightItem(int itemId)
	{
		return hiddenCache.computeIfAbsent(itemId, id ->
		{
			ItemComposition item = client.getItemDefinition(id);
			String name = item.getName();
			for (String pattern : alwaysShow)
			{
				if (WildcardMatcher.matches(pattern, name))
				{
					return false;
				}
			}
			// A noted item can only be used, never eaten, drunk or worn
			if (item.getNote() != -1)
			{
				return true;
			}
			return Arrays.stream(item.getInventoryActions())
				.noneMatch(a -> a != null && fightActions.contains(a.toLowerCase()));
		});
	}

	/** Makes non-fight items transparent, or restores them when hiding is off. */
	private void updateItemHiding()
	{
		// Restore straight from the stored widgets, since a closed panel (like the
		// bank) is no longer reachable from its container
		if (!hidingActive())
		{
			if (!fadedSlots.isEmpty())
			{
				restoreItems();
			}
			return;
		}

		for (int containerId : ITEM_CONTAINERS)
		{
			Widget container = client.getWidget(containerId);
			Widget[] slots = container == null ? null : container.getDynamicChildren();
			if (slots == null)
			{
				continue;
			}

			for (Widget slot : slots)
			{
				if (slot == null)
				{
					continue;
				}

				long key = slotKey(slot);
				int itemId = slot.getItemId();
				boolean hide = !slot.isSelfHidden() && itemId > 0 && slot.getItemQuantity() > 0
					&& isNonFightItem(itemId);
				if (hide)
				{
					if (slot.getOpacity() != TRANSPARENT)
					{
						slot.setOpacity(TRANSPARENT);
					}
					fadedSlots.put(key, slot);
				}
				else if (fadedSlots.remove(key) != null)
				{
					slot.setOpacity(0);
				}
			}
		}
	}

	private void restoreItems()
	{
		for (Widget slot : fadedSlots.values())
		{
			slot.setOpacity(0);
		}
		fadedSlots.clear();
	}

	/** Whether the item in a slot is hidden by the item hiding. */
	boolean isFaded(Widget slot)
	{
		return fadedSlots.containsKey(slotKey(slot));
	}

	private static long slotKey(Widget slot)
	{
		return ((long) slot.getId() << 16) | (slot.getIndex() & 0xffff);
	}

	// Prayers

	/** Shows the game's glow again on the prayers that are active. */
	private void restorePrayerGlows()
	{
		for (int i = 0; i < PRAYER_COUNT; i++)
		{
			Widget widget = client.getWidget(InterfaceID.Prayerbook.PRAYER1 + i);
			Widget glow = findPrayerGlow(widget);
			if (glow != null)
			{
				Prayer prayer = prayerFor(widget);
				glow.setHidden(prayer == null || !isPrayerActive(prayer));
			}
		}
	}

	/** The child of a prayer widget that draws the game's active glow, or null. */
	private static Widget findPrayerGlow(Widget widget)
	{
		if (widget == null)
		{
			return null;
		}
		if (widget.getSpriteId() == ACTIVE_PRAYER_GLOW_SPRITE)
		{
			return widget;
		}

		for (Widget[] children : new Widget[][]{
			widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				Widget glow = findPrayerGlow(child);
				if (glow != null)
				{
					return glow;
				}
			}
		}
		return null;
	}

	/** The prayer a prayer tab widget belongs to, matched by its name, or null. */
	Prayer prayerFor(Widget widget)
	{
		if (widget == null || widget.getName() == null)
		{
			return null;
		}
		String key = Text.removeTags(widget.getName()).toUpperCase().replaceAll("[^A-Z0-9]+", "_");
		return PRAYERS_BY_NAME.get(key);
	}

	/** Prayer state including clicks the server has not confirmed yet. */
	boolean predictedActive(Prayer prayer)
	{
		Pending pending = pendingPrayers.get(prayer);
		return pending != null ? pending.expected : isPrayerActive(prayer);
	}

	/** Server-confirmed prayer state, unaffected by the client's predicted toggle. */
	boolean isPrayerActive(Prayer prayer)
	{
		return client.getServerVarbitValue(prayer.getVarbit()) == 1;
	}

	private void updateAutocast()
	{
		autocastComponent = -1;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int index = client.getVarbitValue(VarbitID.AUTOCAST_SPELL);
		if (index <= 0)
		{
			return;
		}

		EnumComposition spells = client.getEnum(AUTOCAST_SPELLS_ENUM);
		int spellObj = spells == null ? -1 : spells.getIntValue(index);
		if (spellObj <= 0)
		{
			return;
		}

		autocastComponent = client.getItemDefinition(spellObj).getIntValue(ParamID.SPELL_BUTTON);
	}
}

package com.inventoryhover;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.awt.Color;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.client.config.ConfigDescriptor;
import net.runelite.client.config.ConfigItemDescriptor;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigSectionDescriptor;

/**
 * Copies the plugin's settings to the clipboard as readable JSON, grouped by
 * settings section, and applies settings pasted back from the clipboard. Uses
 * only the clipboard and the config manager, never files.
 */
class SettingsSharing
{
	private static final String EXPORT_MARKER = "click-helpers";
	private static final int EXPORT_VERSION = 1;
	private static final int MAX_IMPORT_CHARS = 64 * 1024;

	/** Config key holding the loadouts as a JSON object of name to exported settings. */
	private static final String LOADOUTS_KEY = "loadouts";

	/** Settings that start something and must never be copied or pasted. */
	private static final Set<String> SKIPPED_KEYS = Set.of("copySettings", "pasteSettings", "practiceMode");

	private static final List<String> TAB_PREFIXES = TabSettings.PREFIXES;

	private final InventoryHoverHighlightConfig config;
	private final ConfigManager configManager;

	/** Keys of the tab settings, found on first use. */
	private Set<String> tabKeys;
	private final Gson gson;

	@Inject
	SettingsSharing(InventoryHoverHighlightConfig config, ConfigManager configManager, Gson gson)
	{
		this.config = config;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Copies the settings to the clipboard; returns a message for the player. */
	String copyToClipboard()
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(exportJson()), null);
		return "Click Helpers settings exported to the clipboard.";
	}

	/** Applies settings from the clipboard; returns a message for the player. */
	String pasteFromClipboard()
	{
		String json;
		try
		{
			json = (String) Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
		}
		catch (Exception e)
		{
			return "Nothing to import: the clipboard has no text.";
		}

		if (json == null || json.length() > MAX_IMPORT_CHARS)
		{
			return "The clipboard does not hold Click Helpers settings.";
		}

		try
		{
			return "Imported " + importJson(json) + " Click Helpers settings.";
		}
		catch (RuntimeException e)
		{
			return "The clipboard does not hold Click Helpers settings.";
		}
	}

	/**
	 * Every stored setting of this plugin, grouped under its settings section
	 * name in the order the config panel shows them, so the export reads like
	 * the panel.
	 */
	private JsonObject currentSettings()
	{
		ConfigDescriptor descriptor = configManager.getConfigDescriptor(config);
		Map<String, String> sectionNames = new HashMap<>();
		JsonObject settings = new JsonObject();
		descriptor.getSections().stream()
			.sorted(Comparator.comparingInt(ConfigSectionDescriptor::position))
			.forEach(section ->
			{
				sectionNames.put(section.key(), section.name());
				settings.add(section.name(), new JsonObject());
			});

		descriptor.getItems().stream()
			.sorted(Comparator.comparingInt(ConfigItemDescriptor::position))
			.filter(item -> !SKIPPED_KEYS.contains(item.key()))
			.forEach(item ->
			{
				String value = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, item.key());
				if (value == null)
				{
					return;
				}
				String section = sectionNames.getOrDefault(item.getItem().section(), "Other");
				if (!settings.has(section))
				{
					settings.add(section, new JsonObject());
				}
				settings.getAsJsonObject(section).addProperty(item.key(), value);
			});

		// Leave out sections with nothing stored
		for (String section : new ArrayList<>(settings.keySet()))
		{
			if (settings.getAsJsonObject(section).size() == 0)
			{
				settings.remove(section);
			}
		}
		return settings;
	}

	/** Copies a changed tab setting to the same setting of the other tabs; other keys are ignored. */
	void syncTabSetting(String key, String value)
	{
		String prefix = tabPrefixOf(key);
		if (prefix == null)
		{
			return;
		}

		String suffix = key.substring(prefix.length());
		for (String other : TAB_PREFIXES)
		{
			String target = other + suffix;
			// Stop when the value already matches, so the change events of the copies end here
			if (other.equals(prefix) || Objects.equals(value, configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, target)))
			{
				continue;
			}
			if (value == null)
			{
				configManager.unsetConfiguration(InventoryHoverHighlightConfig.GROUP, target);
			}
			else
			{
				configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, target, value);
			}
		}
	}

	/** Copies every inventory tab setting to the other tabs. */
	void syncAllTabs()
	{
		for (String key : tabKeys())
		{
			if (key.startsWith(TabSettings.INVENTORY))
			{
				syncTabSetting(key, configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, key));
			}
		}
	}

	/** The tab prefix of a tab setting key, or null for any other key. */
	private String tabPrefixOf(String key)
	{
		if (!tabKeys().contains(key))
		{
			return null;
		}
		for (String prefix : TAB_PREFIXES)
		{
			if (key.startsWith(prefix))
			{
				return prefix;
			}
		}
		return null;
	}

	/** Keys of every setting in a tab section. Matched by section, since general keys like "prayers" share a prefix. */
	private Set<String> tabKeys()
	{
		if (tabKeys == null)
		{
			Set<String> sections = TabSettings.SECTIONS;
			tabKeys = configManager.getConfigDescriptor(config).getItems().stream()
				.filter(item -> sections.contains(item.getItem().section()))
				.map(ConfigItemDescriptor::key)
				.collect(Collectors.toSet());
		}
		return tabKeys;
	}

	private Set<String> settingKeys()
	{
		return configManager.getConfigDescriptor(config).getItems().stream()
			.map(ConfigItemDescriptor::key)
			.filter(key -> !SKIPPED_KEYS.contains(key))
			.collect(Collectors.toSet());
	}

	/** Sections randomize leaves alone: the click chart and the import/export switches. */
	private static final Set<String> NOT_RANDOMIZED_SECTIONS = Set.of(InventoryHoverHighlightConfig.chartSection,
		InventoryHoverHighlightConfig.shareSection);

	/**
	 * Sets every on/off, number, color and choice setting to a random value,
	 * with each tab randomized on its own; returns a message. The click chart,
	 * import/export switches, hotkeys, text lists and hidden settings stay.
	 */
	String randomizeAll()
	{
		Random random = new Random();
		// Sync would copy each tab's random values over the others, so turn it off first
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, "syncTabSettings", false);
		int changed = 0;
		for (ConfigItemDescriptor item : configManager.getConfigDescriptor(config).getItems())
		{
			if (SKIPPED_KEYS.contains(item.key()) || item.key().equals("syncTabSettings") || item.getItem().hidden()
				|| NOT_RANDOMIZED_SECTIONS.contains(item.getItem().section()))
			{
				continue;
			}

			Object value;
			Type type = item.getType();
			if (type == boolean.class || type == Boolean.class)
			{
				value = random.nextBoolean();
			}
			else if (type == int.class || type == Integer.class)
			{
				int min = item.getRange() == null ? 0 : item.getRange().min();
				int max = item.getRange() == null ? 100 : Math.min(item.getRange().max(), 100_000);
				value = min + random.nextInt(Math.max(1, max - min + 1));
			}
			else if (type == Color.class)
			{
				value = new Color(random.nextInt(256), random.nextInt(256), random.nextInt(256),
					item.getAlpha() == null ? 255 : 40 + random.nextInt(216));
			}
			else if (type instanceof Class && ((Class<?>) type).isEnum())
			{
				Object[] options = ((Class<?>) type).getEnumConstants();
				value = options[random.nextInt(options.length)];
			}
			else
			{
				continue;
			}
			configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, item.key(), value);
			changed++;
		}
		return "Randomized " + changed + " settings and turned off tab sync. Load a loadout to go back.";
	}

	// Loadouts: named snapshots of every setting, kept in the plugin's own config, never in files

	/** Loadout names, in the order they were saved. */
	List<String> loadoutNames()
	{
		return new ArrayList<>(loadouts().keySet());
	}

	/** Saves every current setting under a name, replacing a loadout with that name; returns a message. */
	String saveLoadout(String name)
	{
		name = name == null ? "" : name.trim();
		if (name.isEmpty())
		{
			return "Type a name for the loadout first.";
		}
		JsonObject all = loadouts();
		boolean replaced = all.has(name);
		all.add(name, gson.fromJson(exportJson(), JsonObject.class));
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY, gson.toJson(all));
		return (replaced ? "Updated loadout " : "Saved loadout ") + name + ".";
	}

	/** Applies a saved loadout; returns a message. */
	String loadLoadout(String name)
	{
		JsonObject all = loadouts();
		if (name == null || !all.has(name))
		{
			return "Pick a loadout to load.";
		}
		int applied = importJson(gson.toJson(all.get(name)));
		return "Loaded loadout " + name + " (" + applied + " settings).";
	}

	/** Deletes a saved loadout; returns a message. */
	String deleteLoadout(String name)
	{
		JsonObject all = loadouts();
		if (name == null || all.remove(name) == null)
		{
			return "Pick a loadout to delete.";
		}
		configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY, gson.toJson(all));
		return "Deleted loadout " + name + ".";
	}

	private JsonObject loadouts()
	{
		String json = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, LOADOUTS_KEY);
		try
		{
			JsonObject all = json == null ? null : gson.fromJson(json, JsonObject.class);
			return all == null ? new JsonObject() : all;
		}
		catch (JsonParseException e)
		{
			return new JsonObject();
		}
	}

	private String exportJson()
	{
		JsonObject root = new JsonObject();
		root.addProperty("plugin", EXPORT_MARKER);
		root.addProperty("version", EXPORT_VERSION);
		root.add("settings", currentSettings());
		return gson.newBuilder().setPrettyPrinting().create().toJson(root);
	}

	/**
	 * Applies exported settings; returns how many were applied. Settings may be
	 * grouped by section or flat. Unknown keys are skipped.
	 */
	private int importJson(String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null || !root.has("plugin") || !EXPORT_MARKER.equals(root.get("plugin").getAsString())
			|| !root.has("settings") || !root.get("settings").isJsonObject())
		{
			throw new JsonParseException("Not Click Helpers settings");
		}

		Map<String, String> values = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("settings").entrySet())
		{
			if (entry.getValue().isJsonObject())
			{
				for (Map.Entry<String, JsonElement> inner : entry.getValue().getAsJsonObject().entrySet())
				{
					if (inner.getValue().isJsonPrimitive())
					{
						values.put(inner.getKey(), inner.getValue().getAsString());
					}
				}
			}
			else if (entry.getValue().isJsonPrimitive())
			{
				values.put(entry.getKey(), entry.getValue().getAsString());
			}
		}

		Set<String> known = settingKeys();
		int applied = 0;
		for (Map.Entry<String, String> entry : values.entrySet())
		{
			if (known.contains(entry.getKey()))
			{
				configManager.setConfiguration(InventoryHoverHighlightConfig.GROUP, entry.getKey(), entry.getValue());
				applied++;
			}
		}
		return applied;
	}
}

package com.inventoryhover;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * Gear switch practice: lights up random empty inventory slots and times how
 * fast and how cleanly they are all clicked. Runs on the client thread; the
 * side panel only reads the immutable summaries.
 */
class SwitchPractice
{
	/** One finished round. */
	static class Round
	{
		/** From the targets lighting up to the first click. */
		final long reactMillis;
		/** From the first click to the last target clicked. */
		final long switchMillis;
		/** Game ticks the clicks were spread over, 1 when all landed in one tick. */
		final int ticks;
		final int hits;
		final int misses;
		/** Whether the time limit ran out before every target was clicked. */
		final boolean timedOut;

		Round(long reactMillis, long switchMillis, int ticks, int hits, int misses, boolean timedOut)
		{
			this.reactMillis = reactMillis;
			this.switchMillis = switchMillis;
			this.ticks = ticks;
			this.hits = hits;
			this.misses = misses;
			this.timedOut = timedOut;
		}
	}

	/** Averages over the rounds of one practice session, kept for the progress chart. */
	static class Summary
	{
		long time;
		int rounds;
		double reactMillis;
		double switchMillis;
		long bestSwitchMillis;
		double ticks;
		/** Finished rounds done within one tick, 0 to 100. */
		double oneTickRate;
		int timeouts;
		/** Hits as a share of all clicks, 0 to 100. */
		double accuracy;
	}

	enum Result
	{
		HIT,
		MISS,
		IGNORED
	}

	private final Random random = new Random();

	/** Target slot indexes; true once clicked. Insertion order is the click order in ordered mode. */
	private final Map<Integer, Boolean> targets = new LinkedHashMap<>();

	private final List<Round> rounds = new ArrayList<>();

	private long roundStart;
	private long firstClick;
	private int firstTick;
	private int misses;

	/** When the next round may start, in nanoTime. */
	private long nextRound;

	private long sessionStart;

	/** Last finished round, or null. */
	Round lastRound;

	/** Settings, set by the overlay each frame. */
	long roundDelay;
	long extraDelay;
	long timeLimit;
	boolean ordered;
	int roundsPerSession;

	boolean isActive()
	{
		return sessionStart != 0;
	}

	void start(long now)
	{
		reset();
		sessionStart = System.currentTimeMillis();
		nextRound = now;
	}

	/** Ends the session; returns its summary, or null when no round was finished. */
	Summary stop()
	{
		Summary summary = summary();
		reset();
		return summary;
	}

	private void reset()
	{
		targets.clear();
		rounds.clear();
		lastRound = null;
		firstClick = 0;
		misses = 0;
		sessionStart = 0;
	}

	/** Whether the set number of rounds is done, so the session should end. */
	boolean isComplete()
	{
		return isActive() && roundsPerSession > 0 && rounds.size() >= roundsPerSession;
	}

	/** Ends a round that ran out of time, then starts a new one once the pause is over. */
	void update(List<Integer> emptySlots, int count, long now, int tick)
	{
		if (!isActive() || isComplete())
		{
			return;
		}

		if (!targets.isEmpty())
		{
			if (timeLimit > 0 && now - roundStart >= timeLimit)
			{
				int hits = (int) targets.values().stream().filter(b -> b).count();
				misses += targets.size() - hits;
				finishRound(now, tick, hits, true);
			}
			return;
		}

		if (now < nextRound || emptySlots.isEmpty())
		{
			return;
		}

		List<Integer> pool = new ArrayList<>(emptySlots);
		Collections.shuffle(pool, random);
		for (int i = 0; i < Math.min(count, pool.size()); i++)
		{
			targets.put(pool.get(i), false);
		}
		roundStart = now;
		firstClick = 0;
		misses = 0;
	}

	/**
	 * Scores a click in the inventory: a hit on a target not clicked yet (the
	 * next one in ordered mode), a miss anywhere else. Clicks between rounds are
	 * ignored.
	 */
	Result click(int slot, long now, int tick)
	{
		if (!isActive() || targets.isEmpty())
		{
			return Result.IGNORED;
		}

		if (firstClick == 0)
		{
			firstClick = now;
			firstTick = tick;
		}

		Boolean clicked = targets.get(slot);
		if (clicked == null || clicked || (ordered && slot != nextTarget()))
		{
			misses++;
			return Result.MISS;
		}

		targets.put(slot, true);
		if (!targets.containsValue(false))
		{
			finishRound(now, tick, targets.size(), false);
		}
		return Result.HIT;
	}

	private void finishRound(long now, int tick, int hits, boolean timedOut)
	{
		long first = firstClick == 0 ? now : firstClick;
		Round round = new Round(
			(first - roundStart) / 1_000_000,
			(now - first) / 1_000_000,
			firstClick == 0 ? 0 : tick - firstTick + 1,
			hits,
			misses,
			timedOut);
		rounds.add(round);
		lastRound = round;
		targets.clear();
		nextRound = now + roundDelay + (long) (random.nextDouble() * extraDelay);
	}

	/** The slot to click next in ordered mode, or -1. */
	int nextTarget()
	{
		for (Map.Entry<Integer, Boolean> target : targets.entrySet())
		{
			if (!target.getValue())
			{
				return target.getKey();
			}
		}
		return -1;
	}

	/** Target slot indexes mapped to whether they are clicked, in light-up order. */
	Map<Integer, Boolean> targets()
	{
		return targets;
	}

	/** Share of the time limit left in the running round, 1 to 0; 1 with no limit or no round. */
	double timeLeft(long now)
	{
		if (timeLimit <= 0 || targets.isEmpty())
		{
			return 1;
		}
		return Math.max(0, 1 - (double) (now - roundStart) / timeLimit);
	}

	int roundCount()
	{
		return rounds.size();
	}

	/** Averages of this session so far, or null with no finished round. */
	Summary summary()
	{
		if (rounds.isEmpty())
		{
			return null;
		}

		Summary summary = new Summary();
		summary.time = sessionStart;
		summary.rounds = rounds.size();
		summary.bestSwitchMillis = Long.MAX_VALUE;
		int hits = 0;
		int missed = 0;
		int finished = 0;
		int oneTick = 0;
		for (Round round : rounds)
		{
			hits += round.hits;
			missed += round.misses;
			if (round.timedOut)
			{
				summary.timeouts++;
				continue;
			}
			finished++;
			summary.reactMillis += round.reactMillis;
			summary.switchMillis += round.switchMillis;
			summary.bestSwitchMillis = Math.min(summary.bestSwitchMillis, round.switchMillis);
			summary.ticks += round.ticks;
			if (round.ticks <= 1)
			{
				oneTick++;
			}
		}
		if (finished > 0)
		{
			summary.reactMillis /= finished;
			summary.switchMillis /= finished;
			summary.ticks /= finished;
			summary.oneTickRate = oneTick * 100.0 / finished;
		}
		else
		{
			summary.bestSwitchMillis = 0;
		}
		summary.accuracy = hits + missed == 0 ? 0 : hits * 100.0 / (hits + missed);
		return summary;
	}
}

package com.inventoryhover;

import java.awt.Color;
import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Hover, slot background, spotlight and miss dot settings of one tab, read by
 * the tab's key prefix. Resolved values are cached until a setting changes.
 */
@Singleton
class TabSettings
{
	static final String INVENTORY = "inv";
	static final String PRAYERS = "prayer";
	static final String SPELLS = "spell";

	static final List<String> PREFIXES = List.of(INVENTORY, PRAYERS, SPELLS);

	/** Config sections that hold tab settings. */
	static final Set<String> SECTIONS = Set.of(InventoryHoverHighlightConfig.invHoverSection, InventoryHoverHighlightConfig.invSpotlightSection, InventoryHoverHighlightConfig.invMissDotsSection, InventoryHoverHighlightConfig.prayerHoverSection, InventoryHoverHighlightConfig.prayerSpotlightSection, InventoryHoverHighlightConfig.prayerMissDotsSection, InventoryHoverHighlightConfig.spellHoverSection, InventoryHoverHighlightConfig.spellSpotlightSection, InventoryHoverHighlightConfig.spellMissDotsSection);

	static class Tab
	{
		InventoryHoverHighlightConfig.HighlightStyle style;
		Color outlineColor;
		Color fillColor;
		int outlineWidth;
		int cornerRadius;
		int hoverFade;
		int hoverDelay;
		boolean hideWhenMenuOpen;
		boolean discoMode;
		int discoInterval;
		boolean keepIconColors;
		/** Slot background color, or null when off. */
		Color slotBackground;
		boolean spotlight;
		int spotlightRadius;
		Color spotlightDim;
		Color spotlightGlow;
		int spotlightGlowSize;
		boolean spotlightAlways;
		boolean spotlightDeadOnly;
		boolean spotlightFalloff;
		int spotlightFalloffDistance;
		int spotlightFalloffEnd;
		Color spotlightFalloffColor;
		boolean missDots;
		Color missDotColor;
		InventoryHoverHighlightConfig.MissDotShape missDotShape;
		boolean missDotHollow;
		int missDotSize;
		int missDotDuration;
	}

	private final ConfigManager configManager;
	private final Map<String, Tab> cache = new ConcurrentHashMap<>();

	@Inject
	TabSettings(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	Tab get(String prefix)
	{
		return cache.computeIfAbsent(prefix, this::resolve);
	}

	void invalidate()
	{
		cache.clear();
	}

	private Tab resolve(String p)
	{
		Tab tab = new Tab();
		tab.style = read(p + "Style", InventoryHoverHighlightConfig.HighlightStyle.class, InventoryHoverHighlightConfig.HighlightStyle.BOTH);
		tab.outlineColor = read(p + "OutlineColor", Color.class, new Color(255, 255, 255, 120));
		tab.fillColor = read(p + "FillColor", Color.class, new Color(98, 189, 125, 60));
		tab.outlineWidth = read(p + "OutlineWidth", int.class, 1);
		tab.cornerRadius = read(p + "CornerRadius", int.class, 4);
		tab.hoverFade = read(p + "HoverFade", int.class, 400);
		tab.hoverDelay = read(p + "HoverDelay", int.class, 0);
		tab.hideWhenMenuOpen = read(p + "HideWhenMenuOpen", boolean.class, false);
		tab.discoMode = read(p + "DiscoMode", boolean.class, false);
		tab.discoInterval = read(p + "DiscoInterval", int.class, 0);
		tab.keepIconColors = read(p + "KeepIconColors", boolean.class, false);
		tab.slotBackground = read(p + "SlotBackground", boolean.class, false)
			? read(p + "SlotBackgroundColor", Color.class, new Color(60, 60, 70, 90))
			: null;
		tab.spotlight = read(p + "Spotlight", boolean.class, false);
		tab.spotlightRadius = read(p + "SpotlightRadius", int.class, 90);
		tab.spotlightDim = read(p + "SpotlightDim", Color.class, new Color(0, 0, 0, 110));
		tab.spotlightGlow = read(p + "SpotlightGlow", Color.class, new Color(255, 255, 255, 45));
		tab.spotlightGlowSize = read(p + "SpotlightGlowSize", int.class, 30);
		tab.spotlightAlways = read(p + "SpotlightAlways", boolean.class, false);
		tab.spotlightDeadOnly = read(p + "SpotlightDeadOnly", boolean.class, false);
		tab.spotlightFalloff = read(p + "SpotlightFalloff", boolean.class, false);
		tab.spotlightFalloffDistance = read(p + "SpotlightFalloffDistance", int.class, 250);
		tab.spotlightFalloffEnd = read(p + "SpotlightFalloffEnd", int.class, 400);
		tab.spotlightFalloffColor = read(p + "SpotlightFalloffColor", Color.class, new Color(0, 0, 0, 0));
		tab.missDots = read(p + "MissDots", boolean.class, false);
		tab.missDotColor = read(p + "MissDotColor", Color.class, new Color(255, 40, 40, 200));
		tab.missDotShape = read(p + "MissDotShape", InventoryHoverHighlightConfig.MissDotShape.class, InventoryHoverHighlightConfig.MissDotShape.CIRCLE);
		tab.missDotHollow = read(p + "MissDotHollow", boolean.class, false);
		tab.missDotSize = read(p + "MissDotSize", int.class, 4);
		tab.missDotDuration = read(p + "MissDotDuration", int.class, 15);
		return tab;
	}

	/** A stored setting, or its default when it was never set. */
	@SuppressWarnings("unchecked")
	private <T> T read(String key, Type type, T fallback)
	{
		Object value = configManager.getConfiguration(InventoryHoverHighlightConfig.GROUP, key, type);
		return value == null ? fallback : (T) value;
	}
}

